macro_rules! deps {
    () => {
        GenericSequence!();
        ArrayLength!();
    };
}

macro_rules! Remove {
    () => {
        deps!();
        # [doc = " Defines a `GenericSequence` which can be shortened by removing an element at a given index."] # [doc = ""] # [doc = " # Safety"] # [doc = " While the [`remove`](Remove::remove) and [`swap_remove`](Remove::swap_remove) methods are marked safe,"] # [doc = " care must be taken when implementing it. The [`remove_unchecked`](Remove::remove_unchecked)"] # [doc = " and [`swap_remove_unchecked`](Remove::swap_remove_unchecked) methods are unsafe"] # [doc = " and must be used with caution."] pub unsafe trait Remove < T , N : ArrayLength > : GenericSequence < T > { # [doc = " Resulting sequence formed by removing an element at the given index."] type Output : GenericSequence < T > ; # [doc = " Removes an element at the given index, shifting elements"] # [doc = " after the given index to the left to fill the gap, resulting"] # [doc = " in a time complexity of O(n) where `n=N-idx-1`"] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use generic_array::{arr, sequence::Remove};"] # [doc = " let a = arr![1, 2, 3, 4];"] # [doc = ""] # [doc = " let (removed, b) = a.remove(2);"] # [doc = " assert_eq!(removed, 3);"] # [doc = " assert_eq!(b, arr![1, 2, 4]);"] # [doc = " ```"] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics if the index is out of bounds."] # [inline] fn remove (self , idx : usize) -> (T , Self :: Output) { assert ! (idx < N :: USIZE , "Index out of bounds: the len is {} but the index is {}" , N :: USIZE , idx) ; unsafe { self . remove_unchecked (idx) } } # [doc = " Removes an element at the given index, swapping it with the last element."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use generic_array::{arr, sequence::Remove};"] # [doc = " let a = arr![1, 2, 3, 4];"] # [doc = ""] # [doc = " let (removed, b) = a.swap_remove(1);"] # [doc = " assert_eq!(removed, 2);"] # [doc = " assert_eq!(b, arr![1, 4, 3]); // note 4 is now at index 1"] # [doc = " ```"] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics if the index is out of bounds."] fn swap_remove (self , idx : usize) -> (T , Self :: Output) { assert ! (idx < N :: USIZE , "Index out of bounds: the len is {} but the index is {}" , N :: USIZE , idx) ; unsafe { self . swap_remove_unchecked (idx) } } # [doc = " Removes an element at the given index without bounds checking,"] # [doc = " shifting elements after the given index to the left to fill the gap,"] # [doc = " resulting in a time complexity of O(n) where `n=N-idx-1`"] # [doc = ""] # [doc = " See [`remove`](Remove::remove) for an example."] # [doc = ""] # [doc = " # Safety"] # [doc = " The caller must ensure that the index is within bounds, otherwise"] # [doc = " it is undefined behavior."] unsafe fn remove_unchecked (self , idx : usize) -> (T , Self :: Output) ; # [doc = " Removes an element at the given index without bounds checking, swapping it with the last element."] # [doc = ""] # [doc = " See [`swap_remove`](Remove::swap_remove) for an example."] # [doc = ""] # [doc = " # Safety"] # [doc = " The caller must ensure that the index is within bounds, otherwise"] # [doc = " it is undefined behavior."] unsafe fn swap_remove_unchecked (self , idx : usize) -> (T , Self :: Output) ; }
    };
}

Remove!()